def findHeight(N, arr):
    if N == 0:
        return 0
    height = [0] * N
    max_height = 0
    for i in range(N):
        if arr[i] == -1:
            continue
        parent = arr[i]
        height[i] = height[parent] + 1
        if height[i] > max_height:
            max_height = height[i]
    return max_height
